Player:ClearCharacterAppearance.example:
player.CharacterAppearanceLoaded:Connect(function()
    player:ClearCharacterAppearance() -- everyone plays in plain clothes
end)

Player:GetFriendsWhoPlayedAsync.example:
local ok, ids = pcall(function()
    return player:GetFriendsWhoPlayedAsync()
end)
if ok then
    print(#ids .. " friends have played this game")
end

Player:IsFriendsWithAsync.example:
local ok, isFriend = pcall(function()
    return player:IsFriendsWithAsync(otherPlayer.UserId)
end)
if ok and isFriend then
    print("They're friends!")
end

Player.CharacterRemoving.example:
player.CharacterRemoving:Connect(function(character)
    print("Saying goodbye to " .. character.Name .. "'s old body")
end)

Player.OnTeleport.example:
player.OnTeleport:Connect(function(teleportState, placeId)
    print("Teleport state:", teleportState, "to place", placeId)
end)
